import { filterByValue } from "./helpers.js";
import { EXTENSIONS_SQL } from "./sql/extensions.sql.js";
import { ident, literal } from "pg-format";
// src/vendor/postgres-meta/lib/PostgresMetaExtensions.ts
var PostgresMetaExtensions = class {
	constructor(query) {
		this.query = query;
	}
	async list({ limit, offset } = {}) {
		const sql = EXTENSIONS_SQL({
			limit,
			offset
		});
		return await this.query(sql);
	}
	async retrieve({ name }) {
		const nameFilter = filterByValue([name]);
		const sql = EXTENSIONS_SQL({ nameFilter });
		const { data, error } = await this.query(sql);
		if (error) return {
			data,
			error
		};
		else if (data.length === 0) return {
			data: null,
			error: { message: `Cannot find an extension named ${name}` }
		};
		else return {
			data: data[0],
			error
		};
	}
	async create({ name, schema, version, cascade = false }) {
		const sql = `
CREATE EXTENSION ${ident(name)}
  ${schema === void 0 ? "" : `SCHEMA ${ident(schema)}`}
  ${version === void 0 ? "" : `VERSION ${literal(version)}`}
  ${cascade ? "CASCADE" : ""};`;
		const { error } = await this.query(sql);
		if (error) return {
			data: null,
			error
		};
		return await this.retrieve({ name });
	}
	async update(name, { update = false, version, schema }) {
		let updateSql = "";
		if (update) updateSql = `ALTER EXTENSION ${ident(name)} UPDATE ${version === void 0 ? "" : `TO ${literal(version)}`};`;
		const schemaSql = schema === void 0 ? "" : `ALTER EXTENSION ${ident(name)} SET SCHEMA ${ident(schema)};`;
		const sql = `BEGIN; ${updateSql} ${schemaSql} COMMIT;`;
		const { error } = await this.query(sql);
		if (error) return {
			data: null,
			error
		};
		return await this.retrieve({ name });
	}
	async remove(name, { cascade = false } = {}) {
		const { data: extension, error } = await this.retrieve({ name });
		if (error) return {
			data: null,
			error
		};
		const sql = `DROP EXTENSION ${ident(name)} ${cascade ? "CASCADE" : "RESTRICT"};`;
		{
			const { error } = await this.query(sql);
			if (error) return {
				data: null,
				error
			};
		}
		return {
			data: extension,
			error: null
		};
	}
};
export { PostgresMetaExtensions as default };
